import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const html=fs.readFileSync('public/index.html','utf8');
const master=fs.readFileSync('src/clan-online.js','utf8');
assert.ok(html.includes("parent.postMessage({type:&#x27;clanBagAck&#x27;,seq:Number(STATE.ppaClanBagSeq)||0},&#x27;*&#x27;)"),'Magister iframe must acknowledge bag after render');
assert.ok(html.includes("else if(d.type==='clanBagAck'){"),'parent must process acknowledgment');
assert.ok(html.includes("if(q>0&&q===PPA_CLAN_BAG_SEND_SEQ)PPA_CLAN_BAG_ACK_SEQ=q;"),'stale ack ignored');
assert.ok(html.includes("PPA_CLAN_BAG_ACK_SEQ!==PPA_CLAN_BAG_SEND_SEQ"),'unreceived bag must be retried');
assert.ok(html.includes("ppaClanBagSeq:++PPA_CLAN_BAG_SEND_SEQ"),'send uses monotonically incrementing sequence');
assert.ok(html.includes("else if(d.type==='clanReady'){PPA_CLAN_BAG_ACK_SEQ=0;sendClanState();}"),'reload iframe resets old ack');
const oldSaveCount=(html.match(/saveGame\(\)/g)||[]).length;
const block=html.slice(html.indexOf("var PPA_CLAN_BAG_LAST_SYNC='';"),html.indexOf("function clanNotice(text){",html.indexOf("var PPA_CLAN_BAG_LAST_SYNC='';")));
assert.ok(block&&!block.includes('saveGame(')&&!block.includes('INV.bag.splice'),'ack refresh cannot touch actual items');
const keeper=html.slice(html.indexOf("function sendStorageState(){"),html.indexOf("function openStorage(){",html.indexOf("function sendStorageState(){")));
assert.ok(keeper.includes('bag:(INV.bag||[]).map(storageItemForUi)'),'Keeper still uses actual bag');
assert.ok(master.includes('async function clanWarehouseTransferV2'),'server V2 unchanged');
const p=html.match(/else if\(d\.type==='clanReady'\)\{PPA_CLAN_BAG_ACK_SEQ=0;sendClanState\(\);\}else if\(d\.type==='clanBagAck'\)\{var q=Number\(d\.seq\)\|\|0;if\(q>0&&q===PPA_CLAN_BAG_SEND_SEQ\)PPA_CLAN_BAG_ACK_SEQ=q;\}/);
assert.ok(p,'generated parent handler must be parseable');
const context={PPA_CLAN_BAG_SEND_SEQ:7,PPA_CLAN_BAG_ACK_SEQ:0,sendClanState(){context.PPA_CLAN_BAG_SEND_SEQ++}};
vm.createContext(context);
const run=vm.runInContext('function route(d){if(false){}'+p[0]+'} route',context);
run({type:'clanBagAck',seq:6});
assert.equal(context.PPA_CLAN_BAG_ACK_SEQ,0,'stale iframe must not suppress new resends');
run({type:'clanBagAck',seq:7});
assert.equal(context.PPA_CLAN_BAG_ACK_SEQ,7,'matching current receiver receipt accepted');
run({type:'clanReady'});
assert.equal(context.PPA_CLAN_BAG_ACK_SEQ,0,'new iframe must re-ack');
assert.equal(context.PPA_CLAN_BAG_SEND_SEQ,8,'fresh bag sent to newly ready iframe');
assert.equal(oldSaveCount,(html.match(/saveGame\(\)/g)||[]).length,'no writes introduced');
console.log('PASS: Magister iframe ACK only after render, dropped packets retried, stale ACK ignored, reload handshake, Keeper bag source unchanged, no save mutations.');
